
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `vcy_solar_cdo`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `vcy_solar_cdo`;

CREATE TABLE `WARRANTY_TYPE` (
  `warranty_type_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `warranty_type_name` VARCHAR(150) NOT NULL,
  `description` TEXT NULL,
  PRIMARY KEY (`warranty_type_id`),
  UNIQUE KEY `uq_warranty_type_name` (`warranty_type_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `VERIFICATION_STATUS` (
  `verification_status_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `verification_status_name` VARCHAR(150) NOT NULL,
  `description` TEXT NULL,
  PRIMARY KEY (`verification_status_id`),
  UNIQUE KEY `uq_verification_status_name` (`verification_status_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `SCHEDULE_STATUS` (
  `schedule_status_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `schedule_status_name` VARCHAR(150) NOT NULL,
  `description` TEXT NULL,
  PRIMARY KEY (`schedule_status_id`),
  UNIQUE KEY `uq_schedule_status_name` (`schedule_status_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `INSTALLATION_STATUS` (
  `installation_status_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `installation_status_name` VARCHAR(150) NOT NULL,
  `description` TEXT NULL,
  PRIMARY KEY (`installation_status_id`),
  UNIQUE KEY `uq_installation_status_name` (`installation_status_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- COMPANY
CREATE TABLE `COMPANY` (
