-- USERS
CREATE TABLE `USERS` (
  `user_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `last_name` VARCHAR(150) NOT NULL,
  `first_name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(190) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `role_id` INT UNSIGNED NOT NULL,
  `company_id` INT UNSIGNED NULL DEFAULT NULL,
  `contact_number` VARCHAR(30) NULL DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_users_1` (`email`),
  CONSTRAINT `fk_users_role_id` FOREIGN KEY (`role_id`)
    REFERENCES `ROLES` (`role_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_users_company_id` FOREIGN KEY (`company_id`)
    REFERENCES `COMPANY` (`company_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

