  CONSTRAINT `fk_solar_equipment_customer_id` FOREIGN KEY (`customer_id`)
    REFERENCES `CUSTOMER` (`customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_solar_equipment_equipment_type_id` FOREIGN KEY (`equipment_type_id`)
