  CONSTRAINT `fk_installition_customer_id` FOREIGN KEY (`customer_id`)
    REFERENCES `CUSTOMER` (`customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_installation_installation_status_id` FOREIGN KEY (`installation_status_id`)
    REFERENCES `INSTALLATION_STATUS` (`installation_status_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- PURCHASE_RECORD
CREATE TABLE `PURCHASE_RECORD` (
  `purchase_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `customer_id` INT UNSIGNED NOT NULL,
  `equipment_id` INT UNSIGNED NOT NULL,
  `transaction_reference` VARCHAR(150) NULL DEFAULT NULL,
