  `archived_at` DATETIME NULL DEFAULT NULL,
  PRIMARY KEY (`purchase_id`),
  UNIQUE KEY `uq_purchase_record_1` (`purchase_id`, `equipment_id`, `customer_id`),
  CONSTRAINT `fk_purchase_record_customer_id` FOREIGN KEY (`customer_id`)
    REFERENCES `CUSTOMER` (`customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_purchase_record_equipment_id` FOREIGN KEY (`equipment_id`, `customer_id`)
    REFERENCES `SOLAR_EQUIPMENT` (`equipment_id`, `customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_purchase_record_payment_method_id` FOREIGN KEY (`payment_method_id`)
