-- MAINTENANCE_REQUESTS
CREATE TABLE `MAINTENANCE_REQUESTS` (
  `request_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `customer_id` INT UNSIGNED NOT NULL,
  `equipment_id` INT UNSIGNED NOT NULL,
  `purchase_id` INT UNSIGNED NULL DEFAULT NULL,
  `concern` TEXT NOT NULL,
  `service_address` VARCHAR(255) NULL DEFAULT NULL,
  `service_city` VARCHAR(150) NULL DEFAULT NULL,
  `submitted_transaction_details` TEXT NULL,
  `submitted_receipt_path` VARCHAR(512) NULL DEFAULT NULL,
  `request_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status_id` INT UNSIGNED NOT NULL DEFAULT 1,
  `verification_status_id` INT UNSIGNED NOT NULL DEFAULT 1,
  `verified_by` INT UNSIGNED NULL DEFAULT NULL,
  `verified_at` DATETIME NULL DEFAULT NULL,
  `archived_at` DATETIME NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `ix_maintenance_requests_1` (`status_id`, `request_date`),
  CONSTRAINT `fk_maintenance_requests_customer_id` FOREIGN KEY (`customer_id`)
    REFERENCES `CUSTOMER` (`customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_requests_equipment_id` FOREIGN KEY (`equipment_id`, `customer_id`)
    REFERENCES `SOLAR_EQUIPMENT` (`equipment_id`, `customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_requests_purchase_id` FOREIGN KEY (`purchase_id`, `equipment_id`, `customer_id`)
    REFERENCES `PURCHASE_RECORD` (`purchase_id`, `equipment_id`, `customer_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_requests_status_id` FOREIGN KEY (`status_id`)
    REFERENCES `STATUS` (`status_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_requests_verified_by` FOREIGN KEY (`verified_by`)
    REFERENCES `USERS` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_requests_verification_status_id` FOREIGN KEY (`verification_status_id`)
    REFERENCES `VERIFICATION_STATUS` (`verification_status_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- WARRANTY
CREATE TABLE `WARRANTY` (
  `warranty_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
