  `warranty_terms` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `archived_at` DATETIME NULL DEFAULT NULL,
  PRIMARY KEY (`warranty_id`),
  CONSTRAINT `fk_warranty_purchase_id` FOREIGN KEY (`purchase_id`)
    REFERENCES `PURCHASE_RECORD` (`purchase_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_warranty_warranty_type_id` FOREIGN KEY (`warranty_type_id`)
    REFERENCES `WARRANTY_TYPE` (`warranty_type_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

