  CONSTRAINT `fk_maintenance_records_schedule_id` FOREIGN KEY (`schedule_id`, `assignment_id`)
    REFERENCES `SCHEDULES` (`schedule_id`, `assignment_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_maintenance_records_created_by` FOREIGN KEY (`created_by`)
