    REFERENCES `OUTCOME_TYPE` (`outcome_type_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- AUDIT_LOGS: append-only activity history. PHP must insert logs in the same
-- transaction as the business change; creating this table does not auto-log actions.
-- Never log passwords, password hashes, session tokens or receipt contents.
-- record_id is a generic identifier, NOT a foreign key to every business table.
CREATE TABLE `AUDIT_LOGS` (
  `audit_log_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED NOT NULL,
  `action` VARCHAR(30) NOT NULL,
  `table_name` VARCHAR(64) NOT NULL,
  `record_id` INT UNSIGNED NOT NULL,
  `description` TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`audit_log_id`),
  KEY `ix_audit_logs_user_time` (`user_id`, `created_at`),
  KEY `ix_audit_logs_record_time` (`table_name`, `record_id`, `created_at`),
  CONSTRAINT `fk_audit_logs_user_id` FOREIGN KEY (`user_id`)
    REFERENCES `USERS` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

